import React, { useState, useEffect } from 'react';
import api from '../services/api';

function Availability() {
  const [volunteers, setVolunteers] = useState([]);
  const [shifts, setShifts] = useState([]);

  useEffect(() => { loadData(); }, []);

  const loadData = async () => {
    const [v, s] = await Promise.all([api.get('/volunteers.php'), api.get('/shifts.php')]);
    setVolunteers(v.data);
    setShifts(s.data);
  };

  return (
    <div style={{ maxWidth: 800, margin: '0 auto' }}>
      <h1>Disponibilidade</h1>
      <p>Selecione os dias/horarios disponiveis para cada voluntario:</p>
      {volunteers.map(v => (
        <div key={v.id} style={{ marginBottom: 20, padding: 15, backgroundColor: '#fff', borderRadius: 8 }}>
          <strong>{v.name}</strong>
        </div>
      ))}
    </div>
  );
}
export default Availability;
